            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0RB_0LC0RA_1RB1LD_1RA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), (fireo_0RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 3; SCycL 2 0; SWin 2])
      ([SWin 3])
      ([SWin 4; SCycL 2 0; SWin 2; SCycR 2; SWin 1])
      ([SWin 5])); vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), (fireo_0RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([])
      ([])
      ([])
      ([])); vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), (fireo_0RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 3; SCycL 2 0; SWin 2; SCycR 2; SWin 1])
      ([SWin 4; SWinL 6])
      ([SWin 4; SCycL 2 0; SWin 2])
      ([SWin 4])); vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), (fireo_0RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 3; SCycL 2 0; SWin 2; SCycR 2; SWin 3; SWin 1])
      ([SWin 4; SWin 1])
      ([SWin 4; SCycL 2 0; SWin 1])
      ([SWin 3])); vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), (fireo_0RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 1])
      ([SWin 1])
      ([SWin 1])
      ([SWin 1])); vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), (fireo_0RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 3; SCycL 2 0; SWin 1])
      ([SWin 2])
      ([SWin 4; SCycL 2 0; SWin 2; SCycR 2; SWin 4; SWin 4])
      ([SWin 6; SWin 4])); vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), (fireo_0RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 2])
      ([SWin 4; SWin 4])
      ([SWin 2])
      ([SWin 2])); vm_compute; reflexivity.
Qed.

