  - intros p _. apply lap_1RB0LB_0RC0LA_1LB1RD_1LA1RC.
  - intros t Ht p _. apply fire_1RB0LB_0RC0LA_1LB1RD_1LA1RC. exact Ht.
  - exact wit_1RB0LB_0RC0LA_1LB1RD_1LA1RC.
  - apply qcleb_CE_05. reflexivity.
