(** ** The lap *)

Lemma lap_1RB0LB_0RC1LD_1LB1RC_1LC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
