               H1 ltac:(reflexivity) ltac:(reflexivity) HA).
    + destruct (gopar0_1RB0LC_1LA1RD_0RD0LA_1LC1RB p j i E ltac:(lia)) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l0 O0_1RB0LC_1LA1RD_0RD0LA_1LC1RB0 p i [] [] t
               H0 ltac:(reflexivity) ltac:(reflexivity) HA).
  - destruct i as [|i].
