    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0LC_1LC1RB_0RB1LD_1LB1LA 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0LC_1LC1RB_0RB1LD_1LB1LA : existsb (fun tg => cfires tmm_1RB0LC_1LC1RB_0RB1LD_1LB1LA c0 4 tg) pins_1RB0LC_1LC1RB_0RB1LD_1LB1LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_1LC1RB_0RB1LD_1LB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_1LC1RB_0RB1LD_1LB1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_1LC1RB_0RB1LD_1LB1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_1LC1RB_0RB1LD_1LB1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_1LC1RB_0RB1LD_1LB1LA : forall t, ~ In t pins_1RB0LC_1LC1RB_0RB1LD_1LB1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_1LC1RB_0RB1LD_1LB1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2; SCycL 3 0; SWin 7] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LB1LA [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2; SCycL 3 0; SWin 5] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2; SCycL 3 0; SWin 8; SCycR 3; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2; SCycL 3 0; SWin 6] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_1RB0LC_1LC1RB_0RB1LD_1LB1LA : NonHalt tmm_1RB0LC_1LC1RB_0RB1LD_1LB1LA /\ QHBoundTr 32779478 tmm_1RB0LC_1LC1RB_0RB1LD_1LB1LA /\ QuasiHaltsTr tmm_1RB0LC_1LC1RB_0RB1LD_1LB1LA.
Proof.
  apply (lap_qh_stage tmm_1RB0LC_1LC1RB_0RB1LD_1LB1LA pins_1RB0LC_1LC1RB_0RB1LD_1LB1LA Cc 1 4 32779478).
  - exact bootq_1RB0LC_1LC1RB_0RB1LD_1LB1LA.
  - intros p _. apply lap_1RB0LC_1LC1RB_0RB1LD_1LB1LA.
  - intros t Ht p _. apply fire_1RB0LC_1LC1RB_0RB1LD_1LB1LA. exact Ht.
  - exact wit_1RB0LC_1LC1RB_0RB1LD_1LB1LA.
  - apply qcleb_CE_05. reflexivity.
Qed.

Theorem qhtr_1RB0LC_1LC1RB_0RB1LD_1LB1LA : NonHalt tm_1RB0LC_1LC1RB_0RB1LD_1LB1LA /\ QHBoundTr 32779478 tm_1RB0LC_1LC1RB_0RB1LD_1LB1LA /\ QuasiHaltsTr tm_1RB0LC_1LC1RB_0RB1LD_1LB1LA.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0LC_1LC1RB_0RB1LD_1LB1LA). rewrite mirror_ok_1RB0LC_1LC1RB_0RB1LD_1LB1LA. exact qhtrm_1RB0LC_1LC1RB_0RB1LD_1LB1LA. Qed.

