    apply (fireo_1RB1RD_1RC1LB_0LB1RA_0LB0RC [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1RC1LB_0LB1RA_0LB0RC [SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
