    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_1RC1LB_0LB1RA_0LB0RC [SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
