(** 1RB0RB_0LC0RA_1RB1LD_1RA1LC *)
Definition tm_1RB0RB_0LC0RA_1RB1LD_1RA1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StB
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StA
  | StC, S0 => mk S1 DR StB | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RB_0LC0RA_1RB1LD_1RA1LC : list Instr := [(StA, S0)].
Definition tmw_1RB0RB_0LC0RA_1RB1LD_1RA1LC : TM := tm_wrap_trs tm_1RB0RB_0LC0RA_1RB1LD_1RA1LC pins_1RB0RB_0LC0RA_1RB1LD_1RA1LC.
