(** ** Anchor glue -- the only per-machine mathematics *)

(** [rep] at [j = m*i + (c1 + c2)]: the residue cases' only algebra. *)
Lemma repeq_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall (u : list Sym) n m, n = m -> rep u n = rep u m.
Proof. intros u n m ->. reflexivity. Qed.

Lemma repmul_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall (u : list Sym) m i, rep u (m * i) = rep (rep u m) i.
Proof.
  intros u m i. induction i as [|i IH]; [rewrite Nat.mul_0_r; reflexivity|].
  replace (m * S i) with (m + m * i) by lia. rewrite rep_add, IH. reflexivity.
Qed.

Lemma repm_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall (u : list Sym) m i c1 c2,
  rep u (m * i + (c1 + c2)) = rep u c1 ++ rep (rep u m) i ++ rep u c2.
Proof.
  intros u m i c1 c2.
  replace (m * i + (c1 + c2)) with (c1 + (m * i + c2)) by lia.
  rewrite !rep_add, repmul_1RB0RB_0LC0RA_1RB1LD_1RA1LC. reflexivity.
Qed.

Lemma gpar0_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall p j q0 i, cview p = (j, Some q0) ->
  j = 2 * i + 2 ->
  Cc p = cden (Kp q0 ++ [S0]) [] i P0_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 /\ cden (Kp q0 ++ [S0]) [] i P0_1RB0RB_0LC0RA_1RB1LD_1RA1LC1 = Cc (Pos.succ p).
Proof.
  intros p j q0 i E Hj. destruct (KpCounter.cview_some_K p j q0 E) as (H1 & H2).
  rewrite (repeq_1RB0RB_0LC0RA_1RB1LD_1RA1LC [S1] _ (2 * i + (0 + 2))) in H1 by lia.
  rewrite (repeq_1RB0RB_0LC0RA_1RB1LD_1RA1LC [S0] _ (2 * i + (0 + 2))) in H2 by lia.
  rewrite repm_1RB0RB_0LC0RA_1RB1LD_1RA1LC in H1, H2.
  unfold Cc_1RB0RB_0LC0RA_1RB1LD_1RA1LC, cden, P0_1RB0RB_0LC0RA_1RB1LD_1RA1LC0, P0_1RB0RB_0LC0RA_1RB1LD_1RA1LC1; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  split; [rewrite H1 | rewrite H2]; cbn [rep app Nat.mul Nat.add]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity.
Qed.

