Lemma lapi_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  pose proof (Nat.div_mod_eq j 2) as Hd.
  pose proof (Nat.mod_upper_bound j 2 ltac:(discriminate)) as Hm.
  set (i := j / 2) in *. set (r := j mod 2) in *. clearbody i r.
  destruct r as [|[|r]]; [idtac | idtac | exfalso; lia].
  - destruct i as [|i].
    + assert (Ej : j = 0) by lia. subst j.
      destruct (gpar1_1RB0RB_0LC0RA_1RB1LD_1RA1LC p q0 E) as (HA & HB).
      exists (0 * 0 + 2). split; [lia|]. rewrite HA.
      rewrite (srun_sound tm false true chp1_1RB0RB_0LC0RA_1RB1LD_1RA1LC P1_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 P1_1RB0RB_0LC0RA_1RB1LD_1RA1LC1 0 2
                 run_p1_1RB0RB_0LC0RA_1RB1LD_1RA1LC (Kp q0 ++ [S0]) [] 0 ltac:(discriminate) ltac:(reflexivity)).
      f_equal. exact HB.
    + destruct (gpar0_1RB0RB_0LC0RA_1RB1LD_1RA1LC p j q0 i E ltac:(lia)) as (HA & HB).
      exists (4 * i + 6). split; [lia|]. rewrite HA.
      rewrite (srun_sound tm false true chp0_1RB0RB_0LC0RA_1RB1LD_1RA1LC P0_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 P0_1RB0RB_0LC0RA_1RB1LD_1RA1LC1 4 6
                 run_p0_1RB0RB_0LC0RA_1RB1LD_1RA1LC (Kp q0 ++ [S0]) [] i ltac:(discriminate) ltac:(reflexivity)).
      f_equal. exact HB.
  - destruct (gpar2_1RB0RB_0LC0RA_1RB1LD_1RA1LC p j q0 i E ltac:(lia)) as (HA & HB).
    exists (4 * i + 4). split; [lia|]. rewrite HA.
    rewrite (srun_sound tm false true chp2_1RB0RB_0LC0RA_1RB1LD_1RA1LC P2_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 P2_1RB0RB_0LC0RA_1RB1LD_1RA1LC1 4 4
               run_p2_1RB0RB_0LC0RA_1RB1LD_1RA1LC (Kp q0 ++ [S0]) [] i ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma lbl_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma gopar0_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall p j i, cview p = (S j, None) ->
  j = 2 * i + 2 ->
  Cc p = cden [] [] i O0_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 /\
  lift (cden [] [] i O0_1RB0RB_0LC0RA_1RB1LD_1RA1LC1) = lift (Cc (Pos.succ p)).
Proof.
  intros p j i E Hj. destruct (KpCounter.cview_none_K p j E) as (H1 & H2).
  rewrite (repeq_1RB0RB_0LC0RA_1RB1LD_1RA1LC [S1] _ (2 * i + (3 + 0))) in H1 by lia.
  rewrite (repeq_1RB0RB_0LC0RA_1RB1LD_1RA1LC [S0] _ (2 * i + (3 + 0))) in H2 by lia.
  rewrite repm_1RB0RB_0LC0RA_1RB1LD_1RA1LC in H1, H2.
  split.
  - unfold Cc_1RB0RB_0LC0RA_1RB1LD_1RA1LC, cden, O0_1RB0RB_0LC0RA_1RB1LD_1RA1LC0; cbn [c_st c_l c_h c_r].
    unfold sden; cbn [s_pre s_u s_a s_b s_post].
    replace (1 * i + 0) with i by lia.
    rewrite H1; cbn [rep app Nat.mul Nat.add]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity.
  - assert (HD : cden [] [] i O0_1RB0RB_0LC0RA_1RB1LD_1RA1LC1 = (StB, ([S0;S0;S0] ++ rep [S0;S0] i ++ [S1], S0, []))).
    { unfold cden, O0_1RB0RB_0LC0RA_1RB1LD_1RA1LC1, sden; cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
      replace (1 * i + 0) with i by lia. cbn [rep app Nat.mul Nat.add]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity. }
    assert (HC : Cc (Pos.succ p) = (StB, (([S0;S0;S0] ++ rep [S0;S0] i ++ [S1]) ++ [S0], S0, []))).
    { unfold Cc_1RB0RB_0LC0RA_1RB1LD_1RA1LC. rewrite H2. cbn [rep app Nat.mul Nat.add]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity. }
    rewrite HD, HC. rewrite ?lift_app_blank_l, ?lift_app_blank. reflexivity.
Qed.

