  - destruct (lapi_1RB0RB_0LC0RA_1RB1LD_1RA1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    exact (lapo_1RB0RB_0LC0RA_1RB1LD_1RA1LC p j' E).
