(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall (l0 l1 l2 l3 : list lstep) (t : Instr),
  srun_instr tm true true l0 O0_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 = Some t ->
  srun_instr tm true true l1 O1_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 = Some t ->
  srun_instr tm true true l2 O2_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 = Some t ->
  srun_instr tm true true l3 O3_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l0 l1 l2 l3 t H0 H1 H2 H3 p j E.
  pose proof (Nat.div_mod_eq j 2) as Hd.
  pose proof (Nat.mod_upper_bound j 2 ltac:(discriminate)) as Hm.
  set (i := j / 2) in *. set (r := j mod 2) in *. clearbody i r.
  destruct r as [|[|r]]; [idtac | idtac | exfalso; lia].
  - destruct i as [|i].
    + assert (Ej : j = 0) by lia. subst j.
      destruct (gopar1_1RB0RB_0LC0RA_1RB1LD_1RA1LC p E) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l1 O1_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 p 0 [] [] t
               H1 ltac:(reflexivity) ltac:(reflexivity) HA).
    + destruct (gopar0_1RB0RB_0LC0RA_1RB1LD_1RA1LC p j i E ltac:(lia)) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l0 O0_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 p i [] [] t
               H0 ltac:(reflexivity) ltac:(reflexivity) HA).
  - destruct i as [|i].
    + assert (Ej : j = 1) by lia. subst j.
      destruct (gopar3_1RB0RB_0LC0RA_1RB1LD_1RA1LC p E) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l3 O3_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 p 0 [] [] t
               H3 ltac:(reflexivity) ltac:(reflexivity) HA).
    + destruct (gopar2_1RB0RB_0LC0RA_1RB1LD_1RA1LC p j i E ltac:(lia)) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l2 O2_1RB0RB_0LC0RA_1RB1LD_1RA1LC0 p i [] [] t
               H2 ltac:(reflexivity) ltac:(reflexivity) HA).
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_0LC0RA_1RB1LD_1RA1LC : forall t, ~ In t pins_1RB0RB_0LC0RA_1RB1LD_1RA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_0LC0RA_1RB1LD_1RA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), (fireo_1RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 3; SCycL 2 0; SWin 2])
      ([SWin 3])
      ([SWin 4; SCycL 2 0; SWin 2; SCycR 2; SWin 1])
      ([SWin 5])); vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), (fireo_1RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([])
      ([])
      ([])
      ([])); vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), (fireo_1RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 3; SCycL 2 0; SWin 2; SCycR 2; SWin 1])
      ([SWin 4; SWinL 6])
      ([SWin 4; SCycL 2 0; SWin 2])
      ([SWin 4])); vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), (fireo_1RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 3; SCycL 2 0; SWin 2; SCycR 2; SWin 3; SWin 1])
      ([SWin 4; SWin 1])
      ([SWin 4; SCycL 2 0; SWin 1])
      ([SWin 3])); vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), (fireo_1RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 1])
      ([SWin 1])
      ([SWin 1])
      ([SWin 1])); vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), (fireo_1RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 3; SCycL 2 0; SWin 1])
      ([SWin 2])
      ([SWin 4; SCycL 2 0; SWin 2; SCycR 2; SWin 4; SWin 4])
      ([SWin 6; SWin 4])); vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), (fireo_1RB0RB_0LC0RA_1RB1LD_1RA1LC
      ([SWin 2])
      ([SWin 4; SWin 4])
      ([SWin 2])
      ([SWin 2])); vm_compute; reflexivity.
Qed.

Theorem qhtr_1RB0RB_0LC0RA_1RB1LD_1RA1LC : NonHalt tm_1RB0RB_0LC0RA_1RB1LD_1RA1LC /\ QHBoundTr 32779478 tm_1RB0RB_0LC0RA_1RB1LD_1RA1LC /\ QuasiHaltsTr tm_1RB0RB_0LC0RA_1RB1LD_1RA1LC.
Proof.
  apply (lap_qh_stage tm_1RB0RB_0LC0RA_1RB1LD_1RA1LC pins_1RB0RB_0LC0RA_1RB1LD_1RA1LC Cc 1 1 32779478).
  - exact bootq_1RB0RB_0LC0RA_1RB1LD_1RA1LC.
  - intros p _. apply lap_1RB0RB_0LC0RA_1RB1LD_1RA1LC.
  - intros t Ht p _. apply fire_1RB0RB_0LC0RA_1RB1LD_1RA1LC. exact Ht.
  - exact wit_1RB0RB_0LC0RA_1RB1LD_1RA1LC.
  - apply qcleb_CE_05. reflexivity.
Qed.

