Definition tm_0RB0LC_1LC1RB_0RB1LD_1LB1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S1 DL StA end.

(** Its mirror 0LB0RC_1RC1LB_0LB1RD_1RB1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
