(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
Proof.
  intros p j q0 E. destruct (Alph_110_111_111.cview_some_Alph_110_111_111 p j q0 E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_0RB1LD_1LB1LA, cden, A0_0RB0LC_1LC1RB_0RB1LD_1LB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A1_0RB0LC_1LC1RB_0RB1LD_1LB1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_110_111_111.cview_some_Alph_110_111_111 p j q0 E) as (_ & H2).
  unfold Cc_0RB0LC_1LC1RB_0RB1LD_1LB1LA, cden, A1_0RB0LC_1LC1RB_0RB1LD_1LB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 10), (cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A1_0RB0LC_1LC1RB_0RB1LD_1LB1LA).
  split; [lia|]. split; [| exact (gei_0RB0LC_1LC1RB_0RB1LD_1LB1LA p j q0 E)].
  rewrite (gsi_0RB0LC_1LC1RB_0RB1LD_1LB1LA p j q0 E).
  exact (srun_sound tm false true chi_0RB0LC_1LC1RB_0RB1LD_1LB1LA A0_0RB0LC_1LC1RB_0RB1LD_1LB1LA A1_0RB0LC_1LC1RB_0RB1LD_1LB1LA 6 10
           run_int_0RB0LC_1LC1RB_0RB1LD_1LB1LA (Ap_Alph_110_111_111 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
Proof.
  intros p j E. destruct (Alph_110_111_111.cview_none_Alph_110_111_111 p j E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_0RB1LD_1LB1LA, cden, B0_0RB0LC_1LC1RB_0RB1LD_1LB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_1LC1RB_0RB1LD_1LB1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_110_111_111.cview_none_Alph_110_111_111 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LC_1LC1RB_0RB1LD_1LB1LA
             = (StB, (rep [S1;S1;S0] (S j) ++ [S1;S1;S1], S0, []))).
  { unfold cden, B1_0RB0LC_1LC1RB_0RB1LD_1LB1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S1;S0] (S j) ++ [S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LC_1LC1RB_0RB1LD_1LB1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0LC_1LC1RB_0RB1LD_1LB1LA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_0RB1LD_1LB1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LC_1LC1RB_0RB1LD_1LB1LA B0_0RB0LC_1LC1RB_0RB1LD_1LB1LA B1_0RB0LC_1LC1RB_0RB1LD_1LB1LA 6 12 p j' [] []).
    + exact run_ovf_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LC_1LC1RB_0RB1LD_1LB1LA p j' E).
    + exact (geo_0RB0LC_1LC1RB_0RB1LD_1LB1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0LC_1LC1RB_0RB1LD_1LB1LA : stepn tmm_0RB0LC_1LC1RB_0RB1LD_1LB1LA 7 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_0RB0LC_1LC1RB_0RB1LD_1LB1LA 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB0LC_1LC1RB_0RB1LD_1LB1LA 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB0LC_1LC1RB_0RB1LD_1LB1LA : existsb (fun tg => cfires tmm_0RB0LC_1LC1RB_0RB1LD_1LB1LA c0 7 tg) pins_0RB0LC_1LC1RB_0RB1LD_1LB1LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC1RB_0RB1LD_1LB1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_0RB1LD_1LB1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_0RB1LD_1LB1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC1RB_0RB1LD_1LB1LA : forall t, ~ In t pins_0RB0LC_1LC1RB_0RB1LD_1LB1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2; SCycL 3 0; SWin 7] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_0RB1LD_1LB1LA [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2; SCycL 3 0; SWin 5] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2; SCycL 3 0; SWin 8; SCycR 3; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_0RB1LD_1LB1LA [SWinR 2; SCycL 3 0; SWin 6] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_0RB0LC_1LC1RB_0RB1LD_1LB1LA : NonHalt tmm_0RB0LC_1LC1RB_0RB1LD_1LB1LA /\ QHBoundTr 32779478 tmm_0RB0LC_1LC1RB_0RB1LD_1LB1LA /\ QuasiHaltsTr tmm_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
Proof.
  apply (lap_qh_stage tmm_0RB0LC_1LC1RB_0RB1LD_1LB1LA pins_0RB0LC_1LC1RB_0RB1LD_1LB1LA Cc 1 7 32779478).
  - exact bootq_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
  - intros p _. apply lap_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
  - intros t Ht p _. apply fire_0RB0LC_1LC1RB_0RB1LD_1LB1LA. exact Ht.
  - exact wit_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
  - apply qcleb_CE_05. reflexivity.
Qed.

Theorem qhtr_0RB0LC_1LC1RB_0RB1LD_1LB1LA : NonHalt tm_0RB0LC_1LC1RB_0RB1LD_1LB1LA /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0RB1LD_1LB1LA /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0RB1LD_1LB1LA.
Proof. apply (qh_triple_unmirror 32779478 tm_0RB0LC_1LC1RB_0RB1LD_1LB1LA). rewrite mirror_ok_0RB0LC_1LC1RB_0RB1LD_1LB1LA. exact qhtrm_0RB0LC_1LC1RB_0RB1LD_1LB1LA. Qed.

End B_CE_05_015.

