      ([SWin 1])
      ([SWin 1])); vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), (fireo_0RB0LC_1LC1RD_0RB0LA_1LA1RB
      ([])
      ([])
      ([])
      ([])); vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), (fireo_0RB0LC_1LC1RD_0RB0LA_1LA1RB
      ([SWin 3; SCycL 2 0; SWin 2; SCycR 2; SWin 1])
      ([SWin 4; SWinL 6])
      ([SWin 4; SCycL 2 0; SWin 2])
