    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RD_1RC1RA_1RD1LC_0LC1RB [SWinR 2; SCycL 3 0; SWin 8; SCycR 3; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
