    apply (lap_of_run tm Cc true true cho_1RB1LB_0RC0LC_1LC1RD_1RB0LA B0_1RB1LB_0RC0LC_1LC1RD_1RB0LA B1_1RB1LB_0RC0LC_1LC1RD_1RB0LA 12 20 p j' [] []).
