Lemma lapi_1RB1LA_0RC0RD_1LC1LD_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  pose proof (Nat.div_mod_eq j 2) as Hd.
  pose proof (Nat.mod_upper_bound j 2 ltac:(discriminate)) as Hm.
  set (i := j / 2) in *. set (r := j mod 2) in *. clearbody i r.
  destruct r as [|[|r]]; [idtac | idtac | exfalso; lia].
  - destruct i as [|i].
    + assert (Ej : j = 0) by lia. subst j.
      destruct (gpar1_1RB1LA_0RC0RD_1LC1LD_0LA0RB p q0 E) as (HA & HB).
      exists (0 * 0 + 4). split; [lia|]. rewrite HA.
      rewrite (srun_sound tm false true chp1_1RB1LA_0RC0RD_1LC1LD_0LA0RB P1_1RB1LA_0RC0RD_1LC1LD_0LA0RB0 P1_1RB1LA_0RC0RD_1LC1LD_0LA0RB1 0 4
                 run_p1_1RB1LA_0RC0RD_1LC1LD_0LA0RB (Kp q0 ++ [S0]) [] 0 ltac:(discriminate) ltac:(reflexivity)).
      f_equal. exact HB.
    + destruct (gpar0_1RB1LA_0RC0RD_1LC1LD_0LA0RB p j q0 i E ltac:(lia)) as (HA & HB).
      exists (4 * i + 8). split; [lia|]. rewrite HA.
      rewrite (srun_sound tm false true chp0_1RB1LA_0RC0RD_1LC1LD_0LA0RB P0_1RB1LA_0RC0RD_1LC1LD_0LA0RB0 P0_1RB1LA_0RC0RD_1LC1LD_0LA0RB1 4 8
                 run_p0_1RB1LA_0RC0RD_1LC1LD_0LA0RB (Kp q0 ++ [S0]) [] i ltac:(discriminate) ltac:(reflexivity)).
      f_equal. exact HB.
  - destruct (gpar2_1RB1LA_0RC0RD_1LC1LD_0LA0RB p j q0 i E ltac:(lia)) as (HA & HB).
    exists (4 * i + 4). split; [lia|]. rewrite HA.
    rewrite (srun_sound tm false true chp2_1RB1LA_0RC0RD_1LC1LD_0LA0RB P2_1RB1LA_0RC0RD_1LC1LD_0LA0RB0 P2_1RB1LA_0RC0RD_1LC1LD_0LA0RB1 4 4
               run_p2_1RB1LA_0RC0RD_1LC1LD_0LA0RB (Kp q0 ++ [S0]) [] i ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

