      ([SWin 2])
      ([SWin 2])
      ([SWin 2])
      ([SWin 2])); vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), (fireo_1RB____1LC0RB_0LD1RB_0LC1RB
      ([SWin 5; SCycL 2 0; SWin 2])
      ([SWin 5])
      ([SWin 6; SCycL 2 0; SWin 2])
      ([SWin 6])); vm_compute; reflexivity.
  - (* C1 *)
