      ([SWin 1])
      ([SWin 1])
      ([SWin 1])
      ([SWin 1])); vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), (fireo_1RB____1LC0RB_0LD1RB_0LC1RB
      ([SWin 5; SCycL 2 0; SWin 2; SCycR 2; SWin 1])
      ([SWin 6])
