      exists (0 * 0 + 8), (cden [] [] 0 O1_1RB____1LC0RB_0LD1RB_0LC1RD1).
      split; [| split; [exact HB | lia]].
      rewrite HA. exact (srun_sound tm true true cho1_1RB____1LC0RB_0LD1RB_0LC1RD O1_1RB____1LC0RB_0LD1RB_0LC1RD0 O1_1RB____1LC0RB_0LD1RB_0LC1RD1 0 8
