                 run_o0_1RB____1LC0RB_0LD1RB_0LC1RD [] [] i ltac:(reflexivity) ltac:(reflexivity)).
  - destruct i as [|i].
    + assert (Ej : j = 1) by lia. subst j.
      destruct (gopar3_1RB____1LC0RB_0LD1RB_0LC1RD p E) as (HA & HB).
      exists (0 * 0 + 12), (cden [] [] 0 O3_1RB____1LC0RB_0LD1RB_0LC1RD1).
