(** ** The lap *)

Lemma lap_1RB____1LC0RB_0LD1RB_0LC1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB____1LC0RB_0LD1RB_0LC1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    exact (lapo_1RB____1LC0RB_0LD1RB_0LC1RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB____1LC0RB_0LD1RB_0LC1RD : stepn tmm_1RB____1LC0RB_0LD1RB_0LC1RD 7 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB____1LC0RB_0LD1RB_0LC1RD 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB____1LC0RB_0LD1RB_0LC1RD 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
