(** ** The lap *)

Lemma lap_1RB____1LC0RD_0LC1RD_1LC0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
