  - destruct (lapi_1RB____1LC0RD_0LC1RD_1LC0RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    exact (lapo_1RB____1LC0RD_0LC1RD_1LC0RB p j' E).
Qed.

