(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0RC0RD_1RD1LA_0LC0RB : forall (l0 l1 l2 l3 : list lstep) (t : Instr),
  srun_instr tm true true l0 O0_1RB1LC_0RC0RD_1RD1LA_0LC0RB0 = Some t ->
  srun_instr tm true true l1 O1_1RB1LC_0RC0RD_1RD1LA_0LC0RB0 = Some t ->
  srun_instr tm true true l2 O2_1RB1LC_0RC0RD_1RD1LA_0LC0RB0 = Some t ->
  srun_instr tm true true l3 O3_1RB1LC_0RC0RD_1RD1LA_0LC0RB0 = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l0 l1 l2 l3 t H0 H1 H2 H3 p j E.
  pose proof (Nat.div_mod_eq j 2) as Hd.
  pose proof (Nat.mod_upper_bound j 2 ltac:(discriminate)) as Hm.
  set (i := j / 2) in *. set (r := j mod 2) in *. clearbody i r.
  destruct r as [|[|r]]; [idtac | idtac | exfalso; lia].
  - destruct i as [|i].
    + assert (Ej : j = 0) by lia. subst j.
      destruct (gopar1_1RB1LC_0RC0RD_1RD1LA_0LC0RB p E) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l1 O1_1RB1LC_0RC0RD_1RD1LA_0LC0RB0 p 0 [] [] t
               H1 ltac:(reflexivity) ltac:(reflexivity) HA).
    + destruct (gopar0_1RB1LC_0RC0RD_1RD1LA_0LC0RB p j i E ltac:(lia)) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l0 O0_1RB1LC_0RC0RD_1RD1LA_0LC0RB0 p i [] [] t
               H0 ltac:(reflexivity) ltac:(reflexivity) HA).
  - destruct i as [|i].
    + assert (Ej : j = 1) by lia. subst j.
      destruct (gopar3_1RB1LC_0RC0RD_1RD1LA_0LC0RB p E) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l3 O3_1RB1LC_0RC0RD_1RD1LA_0LC0RB0 p 0 [] [] t
               H3 ltac:(reflexivity) ltac:(reflexivity) HA).
    + destruct (gopar2_1RB1LC_0RC0RD_1RD1LA_0LC0RB p j i E ltac:(lia)) as (HA & _).
      exact (fire_of_run_instr tm Cc true true l2 O2_1RB1LC_0RC0RD_1RD1LA_0LC0RB0 p i [] [] t
               H2 ltac:(reflexivity) ltac:(reflexivity) HA).
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0RC0RD_1RD1LA_0LC0RB : forall t, ~ In t pins_1RB1LC_0RC0RD_1RD1LA_0LC0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0RC0RD_1RD1LA_0LC0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), (fireo_1RB1LC_0RC0RD_1RD1LA_0LC0RB
      ([SWin 3; SCycL 2 0; SWin 1])
      ([SWin 2])
      ([SWin 4; SCycL 2 0; SWin 2; SCycR 2; SWin 4; SWin 4])
      ([SWin 6; SWin 4])); vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), (fireo_1RB1LC_0RC0RD_1RD1LA_0LC0RB
      ([SWin 2])
      ([SWin 4; SWin 4])
      ([SWin 2])
      ([SWin 2])); vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), (fireo_1RB1LC_0RC0RD_1RD1LA_0LC0RB
      ([SWin 3; SCycL 2 0; SWin 2])
      ([SWin 3])
      ([SWin 4; SCycL 2 0; SWin 2; SCycR 2; SWin 1])
      ([SWin 5])); vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), (fireo_1RB1LC_0RC0RD_1RD1LA_0LC0RB
