(** ** Anchor glue -- the only per-machine mathematics *)

(** [rep] at [j = m*i + (c1 + c2)]: the residue cases' only algebra. *)
Lemma repeq_1RB1LD_1LC0RC_0LD0RB_1RC1LA : forall (u : list Sym) n m, n = m -> rep u n = rep u m.
Proof. intros u n m ->. reflexivity. Qed.

Lemma repmul_1RB1LD_1LC0RC_0LD0RB_1RC1LA : forall (u : list Sym) m i, rep u (m * i) = rep (rep u m) i.
Proof.
  intros u m i. induction i as [|i IH]; [rewrite Nat.mul_0_r; reflexivity|].
  replace (m * S i) with (m + m * i) by lia. rewrite rep_add, IH. reflexivity.
Qed.

Lemma repm_1RB1LD_1LC0RC_0LD0RB_1RC1LA : forall (u : list Sym) m i c1 c2,
  rep u (m * i + (c1 + c2)) = rep u c1 ++ rep (rep u m) i ++ rep u c2.
Proof.
  intros u m i c1 c2.
  replace (m * i + (c1 + c2)) with (c1 + (m * i + c2)) by lia.
  rewrite !rep_add, repmul_1RB1LD_1LC0RC_0LD0RB_1RC1LA. reflexivity.
Qed.

Lemma gpar0_1RB1LD_1LC0RC_0LD0RB_1RC1LA : forall p j q0 i, cview p = (j, Some q0) ->
  j = 2 * i + 2 ->
