  rewrite (repeq_1RB1LD_1LC0RC_0LD0RB_1RC1LA [S0] _ (2 * i + (0 + 2))) in H2 by lia.
  rewrite repm_1RB1LD_1LC0RC_0LD0RB_1RC1LA in H1, H2.
  unfold Cc_1RB1LD_1LC0RC_0LD0RB_1RC1LA, cden, P0_1RB1LD_1LC0RC_0LD0RB_1RC1LA0, P0_1RB1LD_1LC0RC_0LD0RB_1RC1LA1; cbn [c_st c_l c_h c_r].
