Lemma lapi_1RB1LD_1LC0RC_0LD0RB_1RC1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  pose proof (Nat.div_mod_eq j 2) as Hd.
  pose proof (Nat.mod_upper_bound j 2 ltac:(discriminate)) as Hm.
  set (i := j / 2) in *. set (r := j mod 2) in *. clearbody i r.
  destruct r as [|[|r]]; [idtac | idtac | exfalso; lia].
  - destruct i as [|i].
    + assert (Ej : j = 0) by lia. subst j.
      destruct (gpar1_1RB1LD_1LC0RC_0LD0RB_1RC1LA p q0 E) as (HA & HB).
      exists (0 * 0 + 2). split; [lia|]. rewrite HA.
      rewrite (srun_sound tm false true chp1_1RB1LD_1LC0RC_0LD0RB_1RC1LA P1_1RB1LD_1LC0RC_0LD0RB_1RC1LA0 P1_1RB1LD_1LC0RC_0LD0RB_1RC1LA1 0 2
                 run_p1_1RB1LD_1LC0RC_0LD0RB_1RC1LA (Kp q0 ++ [S0]) [] 0 ltac:(discriminate) ltac:(reflexivity)).
      f_equal. exact HB.
    + destruct (gpar0_1RB1LD_1LC0RC_0LD0RB_1RC1LA p j q0 i E ltac:(lia)) as (HA & HB).
      exists (4 * i + 6). split; [lia|]. rewrite HA.
      rewrite (srun_sound tm false true chp0_1RB1LD_1LC0RC_0LD0RB_1RC1LA P0_1RB1LD_1LC0RC_0LD0RB_1RC1LA0 P0_1RB1LD_1LC0RC_0LD0RB_1RC1LA1 4 6
                 run_p0_1RB1LD_1LC0RC_0LD0RB_1RC1LA (Kp q0 ++ [S0]) [] i ltac:(discriminate) ltac:(reflexivity)).
      f_equal. exact HB.
  - destruct (gpar2_1RB1LD_1LC0RC_0LD0RB_1RC1LA p j q0 i E ltac:(lia)) as (HA & HB).
    exists (4 * i + 4). split; [lia|]. rewrite HA.
    rewrite (srun_sound tm false true chp2_1RB1LD_1LC0RC_0LD0RB_1RC1LA P2_1RB1LD_1LC0RC_0LD0RB_1RC1LA0 P2_1RB1LD_1LC0RC_0LD0RB_1RC1LA1 4 4
               run_p2_1RB1LD_1LC0RC_0LD0RB_1RC1LA (Kp q0 ++ [S0]) [] i ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

