(** ** The lap *)

Lemma lap_1RB1LD_1RC0RC_0LD0RB_1RC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
