  - destruct (lapi_1RB1LD_1RC0RC_0LD0RB_1RC1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    exact (lapo_1RB1LD_1RC0RC_0LD0RB_1RC1LA p j' E).
Qed.

