    apply (lap_of_run tm Cc true true cho_0RB1LC_1RC0LA_0RD0LD_1LD1RB B0_0RB1LC_1RC0LA_0RD0LD_1LD1RB B1_0RB1LC_1RC0LA_0RD0LD_1LD1RB 12 20 p j' [] []).
