  - exact bootq_0RB1LC_1RC0LA_0RD0LD_1LD1RB.
  - intros p _. apply lap_0RB1LC_1RC0LA_0RD0LD_1LD1RB.
  - intros t Ht p _. apply fire_0RB1LC_1RC0LA_0RD0LD_1LD1RB. exact Ht.
  - exact wit_0RB1LC_1RC0LA_0RD0LD_1LD1RB.
  - apply qcleb_CE_05. reflexivity.
Qed.

Theorem qhtr_0RB1LC_1RC0LA_0RD0LD_1LD1RB : NonHalt tm_0RB1LC_1RC0LA_0RD0LD_1LD1RB /\ QHBoundTr 32779478 tm_0RB1LC_1RC0LA_0RD0LD_1LD1RB /\ QuasiHaltsTr tm_0RB1LC_1RC0LA_0RD0LD_1LD1RB.
