  rewrite repm_1RB1LD_0LB0RC_0LD0RB_1RC1LA in H1, H2.
  unfold Cc_1RB1LD_0LB0RC_0LD0RB_1RC1LA, cden, P0_1RB1LD_0LB0RC_0LD0RB_1RC1LA0, P0_1RB1LD_0LB0RC_0LD0RB_1RC1LA1; cbn [c_st c_l c_h c_r].
