Lemma fireo_0RB1RC_1LC0RA_0LD0RD_1RD1LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1RC_1LC0RA_0LD0RD_1RD1LB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
