(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LB_0RC0LA_1LB1RD_1LA1RC : forall (l0 l1 l2 l3 : list lstep) (t : Instr),
  srun_instr tm true true l0 O0_0RB0LB_0RC0LA_1LB1RD_1LA1RC0 = Some t ->
  srun_instr tm true true l1 O1_0RB0LB_0RC0LA_1LB1RD_1LA1RC0 = Some t ->
  srun_instr tm true true l2 O2_0RB0LB_0RC0LA_1LB1RD_1LA1RC0 = Some t ->
