  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), (fireo_1RB1LC_1RC0RD_1RD1LA_0LC0RB
      ([SWin 2])
      ([SWin 4; SWin 4])
      ([SWin 2])
      ([SWin 2])); vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
